package protein

import (
	"errors"
)

var (
	// ErrStop indicates a stop codon, which terminates translation.
	ErrStop = errors.New("stop codon")

	// ErrInvalidBase indicates an unrecognized codon.
	ErrInvalidBase = errors.New("invalid base")
)

var codonToProtein = map[string]string{
	"AUG": "Methionine",
	"UUU": "Phenylalanine",
	"UUC": "Phenylalanine",
	"UUA": "Leucine",
	"UUG": "Leucine",
	"UCU": "Serine",
	"UCC": "Serine",
	"UCA": "Serine",
	"UCG": "Serine",
	"UAU": "Tyrosine",
	"UAC": "Tyrosine",
	"UGU": "Cysteine",
	"UGC": "Cysteine",
	"UGG": "Tryptophan",
}

// FromCodon translates a single codon into the corresponding amino acid.
// It returns ErrStop for stop codons and ErrInvalidBase for unknown codons.
func FromCodon(codon string) (string, error) {
	switch codon {
	case "UAA", "UAG", "UGA":
		return "", ErrStop
	}

	protein, ok := codonToProtein[codon]
	if !ok {
		return "", ErrInvalidBase
	}

	return protein, nil
}

// FromRNA translates an RNA sequence into a protein sequence,
// stopping at the first stop codon.
func FromRNA(rna string) ([]string, error) {
	var proteins []string

	for i := 0; i+3 <= len(rna); i += 3 {
		protein, err := FromCodon(rna[i : i+3])
		if err != nil {
			if err == ErrStop {
				return proteins, nil
			}
			return nil, err
		}
		proteins = append(proteins, protein)
	}

	return proteins, nil
}

